  const si = data.create_setup_intent?.data;
  if (!si?.id || !si?.client_secret) {
    throw new Error('Failed to create SetupIntent');
  }
  return {
    setupIntentId: si.id,
    clientSecret: si.client_secret
  };
};

module.exports = async function(data) {
  const body = data.$trigger.body || {};
  const setupIntentId = String(body.setupIntentId || '').trim();
  const email = String(data.read_user?.email || '').trim();
  if (!email) throw new Error('Authenticated user email is required');
  if (!/^seti_[A-Za-z0-9_]+$/.test(setupIntentId)) {
    throw new Error('Valid setupIntentId is required');
  }
  return {
    setupIntentId,
    encodedEmail: encodeURIComponent(email)
  };
};

module.exports = async function(data) {
  const customer = data.find_customer?.data?.data?.[0];
  const si = data.get_setup_intent?.data;
  if (!customer?.id || !si?.id) {
    return { verified: false, error: true, code: 'SETUP_NOT_FOUND', message: 'Card setup could not be verified.' };
  }
  const siCustomerId = typeof si.customer === 'string' ? si.customer : si.customer?.id;
  if (siCustomerId !== customer.id) {
    return { verified: false, error: true, code: 'FORBIDDEN', message: 'SetupIntent does not belong to authenticated customer.' };
  }
  if (si.status !== 'succeeded') {
    return { verified: false, error: true, code: 'SETUP_NOT_SUCCEEDED', status: si.status, message: 'Card setup has not succeeded.' };
  }
  const pm = typeof si.payment_method === 'object' && si.payment_method ? si.payment_method : null;
  const pmCustomerId = typeof pm?.customer === 'string' ? pm.customer : pm?.customer?.id;
  if (!pm?.id || !pm?.card || pmCustomerId !== customer.id) {
    return { verified: false, error: true, code: 'PAYMENT_METHOD_UNATTACHED', message: 'Payment method is not attached to customer.' };
  }
  return {
    verified: true,
    setupIntentId: si.id,
    status: si.status,
    paymentMethodId: pm.id,
    paymentMethod: {
      id: pm.id,
      brand: pm.card.brand,
      last4: pm.card.last4,
      expMonth: pm.card.exp_month,
      expYear: pm.card.exp_year
    }
  };
};

module.exports = async function(data) {
  const body = data.$trigger.body || {};
  const paymentMethodId = String(body.paymentMethodId || '').trim();
  const subscriptionId = body.subscriptionId ? String(body.subscriptionId).trim() : null;
  const email = String(data.read_user?.email || '').trim();
  if (!email) throw new Error('Authenticated user email is required');
  if (!/^pm_[A-Za-z0-9_]+$/.test(paymentMethodId)) {
    throw new Error('Valid paymentMethodId is required');
  }
  return {
    paymentMethodId,
    subscriptionId,
    encodedEmail: encodeURIComponent(email)
  };
};

module.exports = async function(data) {
  const customer = data.find_customer?.data?.data?.[0];
  const pm = data.get_payment_method?.data;
  const pmCustomerId = typeof pm?.customer === 'string' ? pm.customer : pm?.customer?.id;
  if (!customer?.id || !pm?.id || pmCustomerId !== customer.id) {
    throw new Error('Payment method does not belong to authenticated customer');
  }
  return { customerId: customer.id };
};

module.exports = async function(data) {
  const subs = data.list_subscriptions?.data?.data || [];
  const requestedId = data.validate_input?.subscriptionId;
  const eligible = subs.filter(s => ['active', 'trialing', 'past_due'].includes(s.status));
  const match = (requestedId && eligible.find(s => s.id === requestedId)) || eligible[0] || null;
  return {
    activeSubscriptionId: match?.id || null,
    hasActiveSubscription: Boolean(match?.id)
  };
};

module.exports = async function(data) {
  const pmId = data.validate_input.paymentMethodId;
  const subId = data.select_active_subscription?.activeSubscriptionId || null;
  return {
    updated: true,
    defaultPaymentMethodId: pmId,
    customerDefaultUpdated: Boolean(data.update_customer_default?.data?.id),
    subscriptionDefaultUpdated: Boolean(subId ? data.update_subscription_default?.data?.id : true),
    subscriptionId: subId
  };
};
